import{_ as t,o,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const n="/assets/set-cp-site.QYQp-LBC.png",s="/assets/multi-site-selector.Btk82A6d.png",r="/assets/cp-login-screen.Cv4_9MTm.png",g=JSON.parse('{"title":"Multi-site with dedicated SAML based backend login","description":"","frontmatter":{},"headers":[],"relativePath":"examples/multi-site-with-cp-login.md","filePath":"examples/multi-site-with-cp-login.md"}'),l={name:"examples/multi-site-with-cp-login.md"};function d(h,e,c,p,u,m){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="multi-site-with-dedicated-saml-based-backend-login" tabindex="-1">Multi-site with dedicated SAML based backend login <a class="header-anchor" href="#multi-site-with-dedicated-saml-based-backend-login" aria-label="Permalink to &quot;Multi-site with dedicated SAML based backend login&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This example was brought to me in <a href="https://github.com/flipboxfactory/saml-sp/issues/101" target="_blank" rel="noreferrer">issue #101</a>. This user was asking about how to implement SSO/SAML with Azure Ad (see <a href="./../idps/azure-ad.html">Azure AD instructions here</a>) with 2 NuxtJS sites as the frontend and Craft CMS as the headless backend.</p></div><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>As mentioned above, this Craft CMS instance has 2 frontend sites that use NuxtJS to serve content from Craft CMS (headless mode, in this case). Users are not authenticating for authorization to the frontend NuxtJS sites, they are simply consuming the content presented. Content creators need a way to login to the Craft CMS using SAML SSO.</p><h2 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to &quot;Solution&quot;">​</a></h2><h3 id="creating-a-craft-cms-site-for-the-control-panel" tabindex="-1">Creating a Craft CMS Site for the Control Panel <a class="header-anchor" href="#creating-a-craft-cms-site-for-the-control-panel" aria-label="Permalink to &quot;Creating a Craft CMS Site for the Control Panel&quot;">​</a></h3><p>As of Craft CMS version 3.6.10 (maybe before?), we now have an option to set Craft CMS Sites to be disabled on the frontend. We recommend adding a site specifically for the Craft CMS control panel/backend. This allows the plugin to easily utilize the base url for building the SAML documents as needed.</p><p><img src="'+n+'" alt="Create a Site for the Control Panel"></p><h3 id="selecting-the-site-as-the-service-provider-endpoint" tabindex="-1">Selecting the Site as the Service Provider endpoint <a class="header-anchor" href="#selecting-the-site-as-the-service-provider-endpoint" aria-label="Permalink to &quot;Selecting the Site as the Service Provider endpoint&quot;">​</a></h3><p>As of SAML SP Plugin version 2.6.0, multi-site is now fully supported. On the provider edit screen, you can set the site desired to associate the url (base url from the site) as needed.</p><p>At the &quot;My Provider&quot; edit page, on the side bar, select the Craft CMS control panel/backend/admin Site you just created.</p><p><img src="'+s+'" alt="Selecting a site in the Craft CMS Backend"></p><h3 id="login-utilize-cp-login-buttons" tabindex="-1">Login - Utilize CP Login Buttons <a class="header-anchor" href="#login-utilize-cp-login-buttons" aria-label="Permalink to &quot;Login - Utilize CP Login Buttons&quot;">​</a></h3><p>Instruct users to login via the Control Panel login but by using the SAML SP &quot;via&quot; buttons.</p><p><img src="'+r+'" alt="Login to the Control Panel"></p><h3 id="control-panel-on-its-own-domain" tabindex="-1">Control panel on its own domain <a class="header-anchor" href="#control-panel-on-its-own-domain" aria-label="Permalink to &quot;Control panel on its own domain&quot;">​</a></h3><p>As of 5.2.2, the SSO and SLO endpoints (<code>/sso/login</code>, <code>/sso/login/request/...</code>, <code>/sso/logout/...</code>) also respond on control panel requests. This covers a control panel served from its own domain with <code>baseCpUrl</code> and no <code>cpTrigger</code>, where every request on that domain is a control panel request. Earlier versions returned a 404 there.</p><p>Use the same domain for the whole flow: the CP site&#39;s base URL from the step above should be the CP domain, so the login buttons, the ACS URL in your SP metadata and the IdP&#39;s configuration all point at it. The SAML request ID is stored in the session for that domain, and a response arriving on a different domain is rejected.</p>',18)])])}const b=t(l,[["render",d]]);export{g as __pageData,b as default};
